// Base64-encode the downloaded binaries for AURON's vision endpoint.
// AURON never holds a Drive credential itself -- n8n fetches bytes,
// AURON only ever sees the encoded image it's handed.
//
// Runs once for ALL items of the current batch on purpose: $('Loop Over
// Items').all() returns just this batch's items, a plain array read. The
// per-item form ($('Loop Over Items v7').item) makes n8n trace paired items
// back through every previous batch, which gets slower each round and
// eventually times the task runner out on a large folder.

// Die Dauer kommt nicht mehr von hier. Ein mvhd-Parser lief an dieser
// Stelle, solange unbelegt war, ob er dasselbe liefert wie ffprobe im
// Backend. Der Vergleich liegt vor: 31 von 31 Dateien, groesste
// Abweichung 0.000s. Damit war er nur noch eine zweite Quelle fuer eine
// Zahl, die AURON ohnehin selbst aus der Datei liest -- und zwei Quellen
// fuer dieselbe Zahl driften irgendwann auseinander.

const driveItems = $('Loop Over Items v7').all();

// Pfad und Groesse kommen vom Write-Node, NICHT aus $json.
//
// Grund: 'Extract from File v7' verwirft das json des Eingangsitems. Sein
// Parameter options.keepSource hat zwar den Beschreibungs-Default 'json',
// aber das ist ein Feld in einer Collection -- solange es nicht ausdruecklich
// gesetzt ist, liefert getNodeParameter('options') schlicht {} und der Code
// springt ueber das deepCopy hinweg. ingest_path und drive_size_bytes gingen
// so verloren, video_path und expected_size_bytes wurden undefined und fielen
// beim Serialisieren ersatzlos weg. Die API sah 29 Videos ohne Pfad und ohne
// Bild und meldete 0 eingefuegt, 0 fehlgeschlagen.
//
// fileName ist der Pfad, den der Write-Node tatsaechlich geschrieben hat --
// ein belegter Wert, kein durchgereichter Wunsch. Deshalb hier und nicht
// keepSource: der Umweg ueber eine Collection-Option mit irrefuehrendem
// Default waere dieselbe Falle mit einem Pflaster drauf.
const written = $('Write File To Ingest Dir v9').all();

return $input.all().map((item, i) => {
  const drive = driveItems[i].json;
  const mediaType = drive.mimeType || 'image/jpeg';
  const isVideo = mediaType.startsWith('video/');

  if (!isVideo) {
    return {
      json: {
        media_ref: drive.id,
        media_type: 'image',
        image_base64: item.json.image_b64,
        image_media_type: mediaType,
        duration_seconds: null
      }
    };
  }

  const writtenFile = written[i].json;
  if (!writtenFile || !writtenFile.fileName) {
    // Lieber hier abbrechen als ein Video ohne Pfad losschicken: die API
    // weist das inzwischen zurueck, aber der Fehler gehoert dorthin, wo die
    // Ursache sitzt.
    throw new Error(
      `Kein geschriebener Pfad fuer ${drive.id} (Index ${i}) -- ` +
      `Write File To Ingest Dir v9 hat fuer dieses Item kein fileName geliefert.`
    );
  }

  // Videos gehen per Pfad, nicht als Base64: eine 19-MB-Datei waere ~26 MB
  // JSON, und n8n haelt sie hier ohnehin schon komplett im Speicher.
  //
  // expected_size_bytes ist die Groesse, die Drive selbst nennt. AURON
  // vergleicht sie mit den Bytes auf der Platte, bevor es die Datei
  // oeffnet -- ein abgebrochener Schreibvorgang faellt damit an einer Zahl
  // auf und nicht daran, wie kaputt die Datei aussieht.
  return {
    json: {
      media_ref: drive.id,
      media_type: 'video',
      image_base64: null,
      image_media_type: null,
      video_path: writtenFile.fileName,
      expected_size_bytes: writtenFile.drive_size_bytes ?? null,
      // Der Dateiname ist die einzige Aufnahmezeit-Quelle, die ein
      // Lightroom-Export nicht ueberschreibt: der Video-Encoder schreibt die
      // Datei neu und stempelt seinen eigenen Export-Moment als creation_time.
      // Deshalb trug jedes der ersten 30 Videos denselben Nachmittag. AURON
      // liest ein Datum nur, wenn es am Anfang des Namens steht.
      file_name: drive.name || null
    }
  };
});

// Dublettenpruefung VOR dem Download.
// Die Backend-Pruefung in analyze_and_ingest spart nur die Vision-Analyse --
// Drive-Download, Base64 und Payload liefen trotzdem jedes Mal komplett durch.
// Hier fliegen bekannte Dateien raus, bevor sie irgendetwas kosten.
//
// "Bekannt" heisst: im Pool UND dort mit einer echten Analyse. Ein Eintrag mit
// Platzhaltern (Video ohne Frame-Extraktion: theme "video", keine tags, kein
// captured_at) muss wieder durchlaufen duerfen, sonst behaelt er seine leere
// Analyse fuer immer -- genau das war der Zustand von 30 Videos im Pool.
//
// Das Kriterium dafuer lebt ausschliesslich im Backend
// (analysis_completeness.py) und kommt als analysis_complete mit. Hier wird es
// nur gelesen, nie nachgebaut: zwei Definitionen wuerden auseinanderdriften.
const pool = $('AURON: Load Known Refs v7').first().json;
const entries = Array.isArray(pool) ? pool : (pool.items || []);

const withoutField = entries.filter((e) => typeof e.analysis_complete !== 'boolean');
if (entries.length > 0 && withoutField.length > 0) {
  // Fail loud. Ohne das Feld waere `known` leer und ALLE Drive-Dateien gingen
  // in die Vision-Analyse -- ein stiller, teurer Komplettlauf.
  throw new Error(
    `media-pool liefert kein analysis_complete (${withoutField.length}/${entries.length} Eintraege). ` +
    `Backend ist aelter als dieser Workflow. Abbruch, statt alle ${entries.length} Dateien neu zu analysieren.`
  );
}

const analyzed = new Set(
  entries.filter((e) => e.analysis_complete === true).map((e) => e.media_ref).filter(Boolean)
);

// Bewusst der Drive-Node und nicht $input: davor haengt seit v10 der
// Nachtrag des Aufnahmedatums, dessen Ausgabe die API-Antwort ist und
// nicht die Dateiliste. Denselben Fehler gab es schon einmal, als
// 'Extract from File' das json des Eingangsitems verworfen hat.
const driveItems = $('Google Drive: List New Files v7').all();
const fresh = driveItems.filter((item) => !analyzed.has(item.json.id));

console.log(
  `Pool: ${entries.length} Eintraege, davon ${analyzed.size} vollstaendig analysiert, ` +
  `${entries.length - analyzed.size} unvollstaendig. ` +
  `Drive: ${driveItems.length} Dateien -> ${fresh.length} gehen weiter (neu oder unvollstaendig).`
);

return fresh;

// Zielpfad im Uebergabeverzeichnis, plus die Groesse, die Drive selbst nennt.
//
// Die Zuordnung Drive-Item <-> heruntergeladene Bytes laeuft ueber den Index,
// genau wie in 'Prepare AURON Payload v7'. Die Kette bleibt deshalb linear:
// ein Verzweigen und Wiederzusammenfuehren wuerde die Reihenfolge aendern und
// damit media_ref an die falschen Bytes haengen (batchSize ist 5, nicht 1).
//
// Der Name ist deterministisch <drive_id>.<ext>. Der Write-Node oeffnet mit
// O_TRUNC, ueberschreibt also immer -- eine liegengebliebene Datei ist der
// wahrscheinlichste Kandidat fuer einen abgebrochenen Download und wird nie
// wiederverwendet.
const drive = $('Loop Over Items v7').all();

function extensionFor(mimeType) {
  if (mimeType === 'video/quicktime') return 'mov';
  if (mimeType === 'video/x-m4v') return 'm4v';
  if (mimeType.startsWith('video/')) return 'mp4';
  return (mimeType.split('/')[1] || 'bin').toLowerCase();
}

return $input.all().map((item, i) => {
  const file = drive[i].json;
  const mimeType = file.mimeType || '';
  item.json.ingest_path = `/data/images/ingest/${file.id}.${extensionFor(mimeType)}`;
  // Drive liefert size als String; null bleibt null, damit die API weiss,
  // dass es keine Vergleichsgroesse gibt, statt eine 0 zu pruefen.
  item.json.drive_size_bytes = file.size == null ? null : Number(file.size);
  return item;
});
